package main

import (
	"encoding/json"
	"fmt"
	"net/http"
	"os"
	"strconv"
	"strings"
)

type Link struct { Rel string `json:"rel"`; Href string `json:"href"`; Method string `json:"method,omitempty"` }
type User struct { ID int `json:"id"`; Name string `json:"name"`; Links []Link `json:"links"` }
type Post struct { ID int `json:"id"`; UserID int `json:"userId"`; Title string `json:"title"`; Links []Link `json:"links"` }
type RootResponse struct { Links []Link `json:"links"` }

var (users []User; nextUserID = 1; posts []Post; nextPostID = 1)

func postLinks(p Post) []Link {
	return []Link{
		{Rel: "self", Href: fmt.Sprintf("/posts/%d", p.ID)},
		{Rel: "author", Href: fmt.Sprintf("/users/%d", p.UserID)},
		{Rel: "update", Href: fmt.Sprintf("/posts/%d", p.ID), Method: "PUT"},
		{Rel: "delete", Href: fmt.Sprintf("/posts/%d", p.ID), Method: "DELETE"},
	}
}

func rootHandler(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(RootResponse{Links: []Link{{Rel: "self", Href: "/"}, {Rel: "users", Href: "/users"}, {Rel: "posts", Href: "/posts"}}})
}

func usersHandler(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	path := strings.TrimPrefix(r.URL.Path, "/users")
	if path == "" || path == "/" {
		if r.Method == "POST" {
			var body struct { Name string `json:"name"` }
			json.NewDecoder(r.Body).Decode(&body)
			user := User{ID: nextUserID, Name: body.Name, Links: []Link{{Rel: "self", Href: fmt.Sprintf("/users/%d", nextUserID)}, {Rel: "posts", Href: fmt.Sprintf("/users/%d/posts", nextUserID)}}}
			nextUserID++; users = append(users, user)
			w.Header().Set("Location", fmt.Sprintf("/users/%d", user.ID))
			w.WriteHeader(http.StatusCreated); json.NewEncoder(w).Encode(user)
		}
		return
	}
	parts := strings.Split(strings.Trim(path, "/"), "/")
	id, _ := strconv.Atoi(parts[0])
	if len(parts) == 2 && parts[1] == "posts" {
		var r2 []Post
		for _, p := range posts {
			if p.UserID == id {
				p.Links = []Link{{Rel: "self", Href: fmt.Sprintf("/posts/%d", p.ID)}, {Rel: "author", Href: fmt.Sprintf("/users/%d", p.UserID)}}
				r2 = append(r2, p)
			}
		}
		json.NewEncoder(w).Encode(r2); return
	}
	for _, u := range users {
		if u.ID == id {
			u.Links = []Link{{Rel: "self", Href: fmt.Sprintf("/users/%d", u.ID)}, {Rel: "posts", Href: fmt.Sprintf("/users/%d/posts", u.ID)}}
			json.NewEncoder(w).Encode(u); return
		}
	}
	http.NotFound(w, r)
}

func postsHandler(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	parts := strings.Split(strings.Trim(strings.TrimPrefix(r.URL.Path, "/posts"), "/"), "/")
	if len(parts) != 1 { http.NotFound(w, r); return }
	id, _ := strconv.Atoi(parts[0])
	switch r.Method {
	case "GET":
		for _, p := range posts {
			if p.ID == id {
				p.Links = postLinks(p); json.NewEncoder(w).Encode(p); return
			}
		}
		http.NotFound(w, r)
	case "PUT":
		for i, p := range posts {
			if p.ID == id {
				var body struct { Title string `json:"title"` }
				json.NewDecoder(r.Body).Decode(&body)
				posts[i].Title = body.Title; posts[i].Links = postLinks(posts[i])
				json.NewEncoder(w).Encode(posts[i]); return
			}
		}
		http.NotFound(w, r)
	case "DELETE":
		for i, p := range posts {
			if p.ID == id {
				posts = append(posts[:i], posts[i+1:]...); w.WriteHeader(http.StatusNoContent); return
			}
		}
		http.NotFound(w, r)
	}
}

func main() {
	port := os.Getenv("PORT")
	if port == "" { port = "3000" }
	http.HandleFunc("/", rootHandler)
	http.HandleFunc("/users", usersHandler)
	http.HandleFunc("/users/", usersHandler)
	http.HandleFunc("/posts/", postsHandler)
	http.ListenAndServe(":"+port, nil)
}
